import{_ as a,o as i,c as e,ab as o}from"./chunks/framework.DQy4ijAa.js";const h=JSON.parse('{"title":"v8的内存分代","description":"","frontmatter":{},"headers":[],"relativePath":"front/browser/V8引擎的垃圾回收机制.md","filePath":"front/browser/V8引擎的垃圾回收机制.md","lastUpdated":1773383650000}'),p={name:"front/browser/V8引擎的垃圾回收机制.md"};function r(t,l,n,s,u,d){return i(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="v8的内存分代" tabindex="-1">v8的内存分代 <a class="header-anchor" href="#v8的内存分代" aria-label="Permalink to &quot;v8的内存分代&quot;">​</a></h1><p><strong>垃圾回收发生在浏览器空闲时</strong></p><p>V8 引擎将内存分为两个主要区域：</p><h2 id="新生代-young-generation" tabindex="-1">新生代（Young Generation） <a class="header-anchor" href="#新生代-young-generation" aria-label="Permalink to &quot;新生代（Young Generation）&quot;">​</a></h2><ol><li><p>类似于一个临时住宅区</p></li><li><p>存放存活时间短的对象</p></li><li><p>空间较小，通常是 1-8MB</p></li><li><p>使用 <strong>Scavenge 算法</strong>进行垃圾回收</p></li></ol><h3 id="新生代垃圾回收" tabindex="-1">新生代垃圾回收 <a class="header-anchor" href="#新生代垃圾回收" aria-label="Permalink to &quot;新生代垃圾回收&quot;">​</a></h3><p>想象一个搬家的场景：</p><ol><li><p>准备工作</p><ul><li><p>新生代内存被分为两个相等的区域：From 空间和 To 空间</p></li><li><p>正在使用的是 From 空间</p></li></ul></li><li><p>回收过程</p><ul><li><p>当 From 空间快满时，垃圾回收器开始工作</p></li><li><p>检查 From 空间中的对象：</p><ul><li><p>还在使用的对象 → 搬到 To 空间</p></li><li><p>不再使用的对象 → 直接丢弃</p></li></ul></li></ul></li></ol><ul><li>完成后，From 和 To 空间互换角色</li></ul><p>就像把有用的东西搬到新房子，旧房子里剩下的就是垃圾，可以直接清理掉。</p><h2 id="老生代-old-generation" tabindex="-1">老生代（Old Generation） <a class="header-anchor" href="#老生代-old-generation" aria-label="Permalink to &quot;老生代（Old Generation）&quot;">​</a></h2><ol><li><p>像是一个长期居住区</p></li><li><p>存放存活时间长的对象</p></li><li><p>空间较大</p></li><li><p>使用 <strong>标记-清除（Mark-Sweep）</strong> 和 <strong>标记-整理</strong> （Mark-Compact）算法</p></li></ol><h3 id="老生代垃圾回收" tabindex="-1">老生代垃圾回收 <a class="header-anchor" href="#老生代垃圾回收" aria-label="Permalink to &quot;老生代垃圾回收&quot;">​</a></h3><h4 id="标记-清除-mark-sweep" tabindex="-1">标记-清除（Mark-Sweep） <a class="header-anchor" href="#标记-清除-mark-sweep" aria-label="Permalink to &quot;标记-清除（Mark-Sweep）&quot;">​</a></h4><p>这个过程分两步：</p><ol><li><p>标记阶段：</p><ul><li><p>垃圾回收器从根对象（全局对象、正在执行的函数等）开始遍历</p></li><li><p>所有可以访问到的对象都会被标记为&quot;活着&quot;</p></li><li><p>没有被标记的对象就是垃圾</p></li></ul></li><li><p>清除阶段：</p></li></ol><ul><li><p>清理所有没有被标记的对象</p></li><li><p>释放它们占用的内存空间</p></li></ul><hr><h4 id="标记-整理-mark-compact" tabindex="-1">标记-整理（Mark-Compact） <a class="header-anchor" href="#标记-整理-mark-compact" aria-label="Permalink to &quot;标记-整理（Mark-Compact）&quot;">​</a></h4><p>在标记-清除之后，内存可能会出现碎片化（就像小区里零星的空房子）。标记-整理算法会：</p><ol><li>将所有存活的对象向内存的一端移动</li></ol><p>这就像把小区里住户集中到一起，留出一大片连续的空地。</p><p><strong>含义：</strong> 在垃圾回收过程中，标记出哪些对象还“活着”之后，V8 会把这些活着的对象（还在使用的对象）搬运**到内存的一个方向（通常是低地址端）集中放置 ** 。</p><blockquote><p>为什么要这么做？</p><p>因为之前的“标记-清除”虽然清理了垃圾，但留下了很多“空洞”或“碎片”，这就像住户搬走后，房子零零散散地空着，无法高效使用。为了让内存更紧凑、分配更高效，就需要搬家。</p></blockquote><p>举例： 假设一段内存原本是这样的（A、B、C 是活的，X、Y 是死的）：</p><p>执行“将所有活着的对象向一端移动”之后，变成：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[A][B][C][ ][ ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>清理掉边界外的内存</li></ol><p><strong>含义：</strong> 上面已经把活着的对象都集中到了内存的一边，那么“边界外”的部分（也就是后面的空区域）原来可能还保留了垃圾对象的残留信息，现在可以 <strong>统一清空</strong>，释放成一整块干净的空闲内存。</p><blockquote><p>这样做的好处：</p><ol><li>避免内存碎片</li><li>加快下一次内存分配（因为空的内存是一整块连续的）</li></ol></blockquote><h2 id="优化机制" tabindex="-1">优化机制 <a class="header-anchor" href="#优化机制" aria-label="Permalink to &quot;优化机制&quot;">​</a></h2><ol><li><p>增量标记</p><ul><li><p>将标记过程分成小块</p></li><li><p>穿插在 JS 代码执行之间</p></li><li><p>避免长时间暂停程序执行</p></li></ul></li><li><p>惰性清理</p><ul><li><p>不会一次性清理所有垃圾</p></li><li><p>根据需要逐步清理</p></li><li><p>减少程序卡顿</p></li></ul></li></ol>',32)])])}const m=a(p,[["render",r]]);export{h as __pageData,m as default};
